schema.raw:
CREATE TABLE production_type (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL
);

INSERT INTO production_type (name) VALUES ('производство автомобильных двигателей');

CREATE TABLE process (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL
);

INSERT INTO process (name) VALUES ('плавка стали'), ('фрезерование'), ('покраска'), ('каталазирование');

CREATE TABLE equipment (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL
);

INSERT INTO equipment (name) VALUES ('плавильный дом'), ('фрезерный станок'), ('покрасочный цех'), ('каталазный цех');

CREATE TABLE sensor (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) UNIQUE NOT NULL
);

INSERT INTO sensor (name) VALUES ('температура стали'), ('температура фрезерного станка'), ('плотность покраски'), ('температура каталазного цеха');

CREATE TABLE goal (
    id SERIAL PRIMARY KEY,
    description TEXT NOT NULL
);

INSERT INTO goal (description) VALUES ('оптимизация производственного процесса, снижение затрат, улучшение качества продукции');

CREATE TABLE data_source (
    id SERIAL PRIMARY KEY,
    type VARCHAR(255) NOT NULL
);

INSERT INTO data_source (type) VALUES ('датчики на оборудовании'), ('системы управления производством (MES)'), ('системные журналы');

CREATE TABLE update_frequency (
    id SERIAL PRIMARY KEY,
    frequency VARCHAR(255) NOT NULL
);

INSERT INTO update_frequency (frequency) VALUES ('время от времени, в зависимости от типа задачи');

CREATE TABLE critical_parameter (
    id SERIAL PRIMARY KEY,
    sensor_id INT,
    value DECIMAL(10, 2),
    FOREIGN KEY (sensor_id) REFERENCES sensor(id)
);

INSERT INTO critical_parameter (sensor_id, value) VALUES (1, 100.00), (2, 120.00), (3, 0.50);

CREATE TABLE additional_info (
    id SERIAL PRIMARY KEY,
    content TEXT NOT NULL
);

INSERT INTO additional_info (content) VALUES ('важно учитывать сезонные колебания температуры и потребность в точном контроле качества покраски в зимний период');
